        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] array = new int[n];
        for (int i = 0; i < n; i++) {
            array[i] = sc.nextInt();
        }
        int[] parity = new int[n];
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                parity[i] = (array[i] % 2 == 0) ? 1 : -1;
