#include <bits/stdc++.h>
using namespace std;

struct Diff {
    int value;
    int index;
    Diff(int v, int i) : value(v), index(i) {}
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<int> array(n);
    for (int i = 0; i < n; i++) {
        cin >> array[i];
    }
    vector<int> parity(n);
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            parity[i] = (array[i] % 2 == 0) ? 1 : -1;
        } else {
            parity[i] = (array[i] % 2 == 0) ? parity[i - 1] + 1 : parity[i - 1] - 1;
        }
    }
    vector<Diff> differences;
    for (int i = 0; i < n - 1; i++) {
        differences.emplace_back(abs(array[i + 1] - array[i]), i);
    }
    std::sort(differences.begin(), differences.end(), [](const Diff &a, const Diff &b) {
        return a.value < b.value;
    });
    int result = 0;
    for (const auto &d : differences) {
        if (k >= d.value && parity[d.index] == 0) {
            k -= d.value;
            result++;
        }
    }
    cout << result << "\n";
    return 0;
}
